func:
if (!msg.payload || typeof msg.payload !== 'object' || Array.isArray(msg.payload)) {
    node.warn('État technique BACnet invalide');
    return null;
}
flow.set('watchdogKitBacnetState', msg.payload);
return null;

const state = flow.get('watchdogKitBacnetState') || {};
const uuid = env.get('BALENA_DEVICE_UUID');
const name = env.get('BALENA_DEVICE_NAME_AT_INIT') || env.get('BALENA_DEVICE_NAME') || env.get('HOSTNAME');
if (!uuid || !name) {
    node.status({ fill: 'red', shape: 'ring', text: 'identité Balena absente' });
    return null;
}
msg.topic = 'bacnet/gateway/' + uuid + '/heartbeat';
msg.qos = 1;
msg.retain = true;
msg.payload = {
    schema: 'watchdog.heartbeat.v1',
    ts: Date.now(),
    device: { uuid, name, app: env.get('BALENA_APP_NAME') || '', host: env.get('HOSTNAME') || '', protocol: 'bacnet' },
    health: Object.assign({ ok: false, protocol: 'bacnet', status: 'unknown' }, state.health || {}),
    mqtt: Object.assign({ ok: false, connected: false, status: 'unknown' }, state.mqtt || {}),
    buffer: Object.assign({ state: 'unknown', pending: 0 }, state.buffer || {}),
    snapshot: state.snapshot === undefined ? null : state.snapshot,
    supervisor: state.supervisor === undefined ? null : state.supervisor,
    grace: Boolean(state.grace)
};
node.status({ fill: msg.payload.health.ok ? 'green' : 'red', shape: 'dot', text: msg.payload.health.ok ? 'ok' : 'dégradé' });
return msg;
